const write = () => rows.map((row, index) => {
  if (!row.marker) return row.line;
  let indent = indents[index]!;
  if (!out) {
    let extra = INDENT.length;
    while (column(row.indent, extra) < column(indent)) extra++;
    indent = ' '.repeat(extra) + row.indent;
  }
  return indent + marker(index) + row.gap + row.body;
}).join('\n');
